  assert.equal(valueNoise3(1.5, 2.5, 3.5, 9), valueNoise3(1.5, 2.5, 3.5, 9));
  assert.equal(fbm2(0.4, 0.7, 4, 5, 1), fbm2(0.4, 0.7, 4, 5, 1));
  assert.equal(fbm3(0.4, 0.7, 0.9, 1, 5), fbm3(0.4, 0.7, 0.9, 1, 5));
